// Helper to get milliseconds (ESP-IDF equivalent of millis())
static inline uint32_t get_millis() {
    return (uint32_t)(esp_timer_get_time() / 1000);
}

// State
static CommissioningState s_state = CS_UNINITIALIZED;
static char s_status_message[64] = "Initializing...";
static commissioning_callback_t s_callback = nullptr;
static uint32_t s_state_entered_at = 0;
static int s_connection_attempts = 0;

// ============================================================================
// Internal Helpers
// ============================================================================

static void transitionTo(CommissioningState new_state) {
    if (s_state == new_state)
        return;

    CommissioningState old_state = s_state;
    s_state = new_state;
    s_state_entered_at = get_millis();

    // Update NVS
    nvs_set_commissioning_state((int32_t) new_state);

    // Update status message
    const char *state_name = getStateName(new_state);
    snprintf(s_status_message, sizeof(s_status_message), "%s", state_name);

    printf("[Commissioning] %s -> %s\n", getStateName(old_state), state_name);

    display_set_status(s_status_message);

    // Notify callback
    if (s_callback) {
        s_callback(old_state, new_state);
    }
}

// ============================================================================
// State Handlers
// ============================================================================

static CommissioningState handleUninitialized() {
    printf("[Commissioning] Starting commissioning flow: full\n");

    // Full flow - check for existing credentials (or use hardcoded)
#if WIFI_USE_HARDCODED
    printf("[Commissioning] Using hardcoded WiFi credentials\n");
    wifi_station_init();
    return CS_CONNECTING_TO_WIFI;
#else
    if (nvs_has_wifi_credentials()) {
        printf("[Commissioning] Found stored credentials\n");
        wifi_station_init();
        return CS_CONNECTING_TO_WIFI;
    } else {
        printf("[Commissioning] No credentials - starting AP mode\n");
        ap_provisioning_setup();
        char ip_buf[16];
        const char* ip = ap_get_ip_address(ip_buf, sizeof(ip_buf));
        snprintf(s_status_message, sizeof(s_status_message), "Setup: %s", ip ? ip : "192.168.4.1");
        return CS_AP_MODE_PROVISIONING;
    }
#endif
}

static CommissioningState handleAPMode() {
    // Process AP web server
    if (ap_provisioning_loop()) {
        // Credentials received - device will restart
        return CS_AP_MODE_PROVISIONING;
    }

    return CS_AP_MODE_PROVISIONING;
}

static const int MAX_CONNECT_ATTEMPTS = 30;

static CommissioningState handleConnecting() {
    s_connection_attempts++;
    snprintf(s_status_message, sizeof(s_status_message), "Connecting... (%d/%d)",
             s_connection_attempts, MAX_CONNECT_ATTEMPTS);

    display_set_status(s_status_message);
    display_menu_show_progress("Connecting...", (s_connection_attempts * 100) / MAX_CONNECT_ATTEMPTS);

    // Exceeded max attempts - go to AP mode but keep credentials
    if (s_connection_attempts >= MAX_CONNECT_ATTEMPTS) {
        printf("[Commissioning] Max attempts (%d) reached, starting AP mode (credentials preserved)\n",
               MAX_CONNECT_ATTEMPTS);
        wifi_station_disconnect();
        s_connection_attempts = 0;
        ap_provisioning_setup();
        return CS_AP_MODE_PROVISIONING;
    }

    WiFiStatus result = wifi_station_connect();

    switch (result) {
    case WIFI_STATUS_CONNECTED: {
        printf("[Commissioning] WiFi connected!\n");
        char ssid_buf[33], ip_buf[16];
        wifi_station_get_ssid(ssid_buf, sizeof(ssid_buf));
        wifi_station_get_ip(ip_buf, sizeof(ip_buf));
        display_set_wifi_status(true, ssid_buf, ip_buf, wifi_station_get_rssi());
        s_connection_attempts = 0;
        return CS_WIFI_CONNECTED;
    }

    case WIFI_STATUS_FAILED:
        printf("[Commissioning] Connection attempt failed, will retry\n");
        return CS_CONNECTING_TO_WIFI;

    case WIFI_STATUS_NO_CREDENTIALS:
        printf("[Commissioning] No credentials, starting AP mode\n");
        s_connection_attempts = 0;
        ap_provisioning_setup();
        return CS_AP_MODE_PROVISIONING;

    default:
        return CS_CONNECTING_TO_WIFI;
    }
}

static CommissioningState handleWiFiConnected() {
    // No server registration - go straight to functional
    return CS_FUNCTIONAL;
}

static CommissioningState handleFunctional() {
    // Monitor WiFi connection in functional state
    wifi_station_loop();

    if (!wifi_station_is_connected()) {
        printf("[Commissioning] WiFi lost, reconnecting...\n");
        return CS_CONNECTING_TO_WIFI;
    }

    return CS_FUNCTIONAL;
}

static CommissioningState handleError() {
    // Error state - could show error on display, blink LED, etc.
    return CS_ERROR;
}

// ============================================================================
// Public API
// ============================================================================

CommissioningState commissioning_init(void) {
    printf("[Commissioning] Initializing...\n");

    // Initialize NVS
    if (!nvs_handler_init()) {
        printf("[Commissioning] NVS init failed!\n");
        s_state = CS_ERROR;
        return CS_ERROR;
    }

    // Check for stored state
    int32_t stored_state = nvs_get_commissioning_state();
    printf("[Commissioning] Stored state: %ld\n", (long)stored_state);

    // Determine initial state based on stored value and credentials
    if (stored_state == CS_FUNCTIONAL && nvs_has_wifi_credentials()) {
        // Was functional before - try to reconnect
        s_state = CS_UNINITIALIZED;
    } else {
        s_state = CS_UNINITIALIZED;
    }

    display_menu_init();

    s_state_entered_at = get_millis();

    return s_state;
}

CommissioningState commissioning_loop(void) {
    CommissioningState next_state = s_state;

    switch (s_state) {
    case CS_UNINITIALIZED:
        next_state = handleUninitialized();
        break;

    case CS_AP_MODE_PROVISIONING:
        next_state = handleAPMode();
        break;

    case CS_CONNECTING_TO_WIFI:
        next_state = handleConnecting();
        break;

    case CS_WIFI_CONNECTED:
        next_state = handleWiFiConnected();
        break;

    case CS_FUNCTIONAL:
        next_state = handleFunctional();
        break;

    case CS_ERROR:
        next_state = handleError();
        break;

    default:
        printf("[Commissioning] Unknown state: %d\n", (int)s_state);
        next_state = CS_ERROR;
        break;
    }

    if (next_state != s_state) {
        transitionTo(next_state);
    }

    // Note: display_menu_update() is called from the dedicated display_task
    // to avoid SPI bus conflicts

    return s_state;
}

CommissioningState commissioning_get_state(void) {
    return s_state;
}

bool commissioning_set_state(CommissioningState new_state) {
    // Validate transition
    transitionTo(new_state);
    return true;
}

void commissioning_factory_reset(void) {
    printf("[Commissioning] Factory reset requested\n");
    nvs_factory_reset();
}

bool commissioning_is_complete(void) {
    return s_state == CS_FUNCTIONAL;
}

const char *commissioning_get_status_message(void) {
    return s_status_message;
}

void commissioning_set_callback(commissioning_callback_t callback) {
    s_callback = callback;
}